<?php

namespace Workbench\App\Files;

use Illuminate\Support\Str;

/**
 * Workbench /files: a tiny drive kept in the session (folders and file metadata only;
 * file bodies are generated by DemoFileController from the id). Every id that comes
 * from the browser is looked up here first: anything unknown is refused.
 */
final class DemoDrive
{
    private const KEY = 'workbench-files-drive';

    /** @return array<string, array{id: string, name: string, folder: bool, parent: ?string, size: int, type: ?string, modified: string, created: string}> */
    public static function all(): array
    {
        return session(self::KEY) ?? tap(self::seed(), fn ($items) => session([self::KEY => $items]));
    }

    public static function reset(): void
    {
        session()->forget(self::KEY);
    }

    private static function save(array $items): void
    {
        session([self::KEY => $items]);
    }

    public static function get(?string $id): ?array
    {
        return $id === null ? null : (self::all()[$id] ?? null);
    }

    /** @return list<array<string, mixed>> */
    public static function children(?string $parent, string $sort = 'name', string $direction = 'asc'): array
    {
        $all = self::all();
        $items = array_values(array_filter($all, fn ($i) => $i['parent'] === $parent));
        $counts = [];
        foreach ($all as $item) {
            $counts[$item['parent'] ?? ''] = ($counts[$item['parent'] ?? ''] ?? 0) + 1;
        }
        usort($items, function ($a, $b) use ($sort, $direction) {
            if ($a['folder'] !== $b['folder']) {
                return $a['folder'] ? -1 : 1; // folders first, as every file manager does
            }
            $cmp = match ($sort) {
                'modified' => strcmp($a['modified'], $b['modified']),
                'size' => $a['size'] <=> $b['size'],
                default => strnatcasecmp($a['name'], $b['name']),
            };

            return $direction === 'desc' ? -$cmp : $cmp;
        });

        return array_map(fn ($i) => $i + ['count' => $counts[$i['id']] ?? 0], $items);
    }

    /** @return list<array{id: ?string, label: string}> */
    public static function trail(?string $folder): array
    {
        $trail = [];
        for ($item = self::get($folder); $item; $item = self::get($item['parent'])) {
            array_unshift($trail, ['id' => $item['id'], 'label' => $item['name']]);
        }

        return [['id' => null, 'label' => 'My files'], ...$trail];
    }

    /** Folders as x-ui.tree nodes, under a "My files" root. */
    public static function tree(): array
    {
        $all = self::all();
        $build = function (?string $parent) use (&$build, $all): array {
            $nodes = [];
            foreach ($all as $item) {
                if ($item['folder'] && $item['parent'] === $parent) {
                    $children = $build($item['id']);
                    $nodes[] = ['id' => $item['id'], 'label' => $item['name']] + ($children ? ['children' => $children] : []);
                }
            }
            usort($nodes, fn ($a, $b) => strnatcasecmp($a['label'], $b['label']));

            return $nodes;
        };

        return [['id' => 'root', 'label' => 'My files', 'children' => $build(null)]];
    }

    public static function rename(string $id, string $name): ?string
    {
        $all = self::all();
        $name = trim($name);
        if (! isset($all[$id])) {
            return 'That item no longer exists.';
        }
        if ($name === '' || mb_strlen($name) > 255 || preg_match('#[/\\\\]#', $name)) {
            return 'Use a name without slashes, up to 255 characters.';
        }
        foreach ($all as $other) {
            if ($other['id'] !== $id && $other['parent'] === $all[$id]['parent'] && strcasecmp($other['name'], $name) === 0) {
                return 'Another item here already has that name.';
            }
        }
        $all[$id]['name'] = $name;
        $all[$id]['modified'] = now()->toIso8601String();
        self::save($all);

        return null;
    }

    public static function create(?string $parent, string $name): ?string
    {
        $all = self::all();
        $name = trim($name);
        if ($parent !== null && empty($all[$parent]['folder'])) {
            return 'That folder no longer exists.';
        }
        if ($name === '' || mb_strlen($name) > 255 || preg_match('#[/\\\\]#', $name)) {
            return 'Use a name without slashes, up to 255 characters.';
        }
        foreach ($all as $other) {
            if ($other['parent'] === $parent && strcasecmp($other['name'], $name) === 0) {
                return 'Another item here already has that name.';
            }
        }
        $id = 'd'.Str::lower(Str::random(8));
        $all[$id] = self::item($id, $name, true, $parent, 0, null, now()->toIso8601String());
        self::save($all);

        return null;
    }

    public static function addFile(?string $parent, string $name, int $size, ?string $type): void
    {
        $all = self::all();
        $id = 'f'.Str::lower(Str::random(8));
        $all[$id] = self::item($id, $name, false, $parent, $size, $type, now()->toIso8601String());
        self::save($all);
    }

    /** @param list<string> $ids */
    public static function move(array $ids, ?string $target): ?string
    {
        $all = self::all();
        if ($target !== null && empty($all[$target]['folder'])) {
            return 'Choose a folder.';
        }
        foreach ($ids as $id) {
            if (! isset($all[$id])) {
                return 'Some of these items no longer exist.';
            }
            // A folder cannot go into itself or anything inside it.
            for ($p = $target; $p !== null; $p = $all[$p]['parent']) {
                if ($p === $id) {
                    return 'A folder cannot be moved into itself.';
                }
            }
        }
        foreach ($ids as $id) {
            $all[$id]['parent'] = $target;
        }
        self::save($all);

        return null;
    }

    /** @param list<string> $ids */
    public static function delete(array $ids): ?string
    {
        $all = self::all();
        foreach ($ids as $id) {
            if (! isset($all[$id])) {
                return 'Some of these items no longer exist.';
            }
        }
        $gone = $ids;
        do {
            $before = count($gone);
            foreach ($all as $item) {
                if (in_array($item['parent'], $gone, true) && ! in_array($item['id'], $gone, true)) {
                    $gone[] = $item['id'];
                }
            }
        } while (count($gone) !== $before);
        self::save(array_diff_key($all, array_flip($gone)));

        return null;
    }

    private static function item(string $id, string $name, bool $folder, ?string $parent, int $size, ?string $type, string $at): array
    {
        return ['id' => $id, 'name' => $name, 'folder' => $folder, 'parent' => $parent, 'size' => $size, 'type' => $type, 'modified' => $at, 'created' => $at];
    }

    private static function seed(): array
    {
        $at = fn (string $day) => '2026-'.$day.'T10:00:00+01:00';
        $rows = [
            ['invoices', 'Invoices', true, null, 0, null, $at('11-12')],
            ['contracts', 'Contracts and signed agreements for the 2026 Lagos and Abuja distribution partnerships', true, null, 0, null, $at('10-02')],
            ['photos', 'Photos', true, null, 0, null, $at('11-14')],
            ['scans', 'Scans', true, null, 0, null, $at('09-20')],
            ['empty', 'Empty folder', true, null, 0, null, $at('08-01')],
            ['report', 'Quarterly report.pdf', false, null, 2400000, 'application/pdf', $at('11-15')],
            ['notes', 'Meeting notes.md', false, null, 3200, 'text/markdown', $at('11-13')],
            ['cover', 'Album cover.png', false, null, 840000, 'image/png', $at('11-10')],
            ['jingle', 'Jingle demo.wav', false, null, 88244, 'audio/wav', $at('11-09')],
            ['long', 'statement-october-2026-first-bank-business-account-ending-4821-with-every-transaction.csv', false, null, 128000, 'text/csv', $at('11-01')],
            ['archive', 'Old exports.zip', false, null, 31000000, 'application/zip', $at('06-30')],
            ['inv-1042', 'INV-1042.pdf', false, 'invoices', 182000, 'application/pdf', $at('11-12')],
            ['inv-1043', 'INV-1043 for a very long customer name that wraps onto a second line.pdf', false, 'invoices', 176000, 'application/pdf', $at('11-12')],
            ['paid', 'Paid', true, 'invoices', 0, null, $at('11-05')],
            ['inv-0999', 'INV-0999.pdf', false, 'paid', 150000, 'application/pdf', $at('10-28')],
            ['nda', 'Mutual NDA.pdf', false, 'contracts', 98000, 'application/pdf', $at('10-02')],
            ['studio', 'Studio session.png', false, 'photos', 1200000, 'image/png', $at('11-14')],
            ['stage', 'Stage plan.png', false, 'photos', 640000, 'image/png', $at('11-13')],
        ];
        for ($i = 1; $i <= 30; $i++) {
            $rows[] = ['scan-'.$i, sprintf('scan-%04d.pdf', $i), false, 'scans', 100000 + $i * 7919, 'application/pdf', $at(sprintf('09-%02d', min(28, $i)))];
        }
        $items = [];
        foreach ($rows as [$id, $name, $folder, $parent, $size, $type, $when]) {
            $items[$id] = self::item($id, $name, $folder, $parent, $size, $type, $when);
        }

        return $items;
    }
}
